{"cards": [{"node_code": "N_7e278e61a9e36f1b", "definition": "研究各类真空计的工作原理、结构特性、量程范围及真空度测量方法，涵盖从粗真空到高真空的全范围压力监测技术。", "boundary": "聚焦于真空度（总压）的测量原理与仪器本身。包括热导式、电离式、电容式、磁流体式等真空计的物理机制、误差分析及校准标准。边界在于“压力值”的获取，不涉及气体成分分析或泄漏源定位。若涉及真空计在系统中的安装布局或控制逻辑，主挂载至系统节点，但仪器原理归本节点。", "includes": ["皮拉尼计、电离计、电容计、马赫-恩格勒计等真空计的原理与结构", "真空度测量的误差来源、修正方法及标准校准规程", "不同压力区间（粗、中、高、超高真空）的测量技术选型与比较"], "excludes": ["气体成分分析或分压测量（归入分压测量与残余气体分析）", "泄漏检测技术或漏孔模拟（归入真空检漏、漏孔与校准）", "真空阀门、腔体等机械元件及系统控制（归入真空系统、元件与控制）"], "sibling_distinctions": [{"other_code": "N_a1c8872f7944e3c6", "rule": "本节点关注真空度（总压）的数值测量；兄弟节点关注泄漏的存在性、位置及漏率量化。"}, {"other_code": "N_e8b2ce1947ab532c", "rule": "本节点关注总压测量；兄弟节点关注特定气体组分的分压及成分谱分析。"}], "cross_boundary_rule": "若研究重点在于真空计的传感器物理原理、信号处理或精度校准，主挂载至本节点；若研究重点在于真空计在特定工艺中的集成应用或系统联调，可次关联至系统节点，但核心测量技术归本节点。"}, {"node_code": "N_a1c8872f7944e3c6", "definition": "研究真空系统泄漏检测原理、检漏仪器应用、标准漏孔制备与校准，以及漏率测量与泄漏源定位技术。", "boundary": "聚焦于真空系统密封完整性的诊断与量化。包括氦质谱检漏、卤素检漏、气泡检漏等方法，标准漏孔的制造、校准及漏率单位定义。边界在于“泄漏”这一缺陷的检测与量化，不涉及真空度常规监测或气体成分分析。若涉及检漏仪内部真空计原理，可关联至真空计节点，但检漏流程与漏孔标准归本节点。", "includes": ["氦质谱、卤素、气泡等检漏方法的原理、操作流程及仪器选型", "标准漏孔的制备工艺、漏率校准方法及不确定度评定", "真空系统泄漏源定位技术、漏率测量标准及密封性测试规范"], "excludes": ["常规真空度（总压）测量（归入真空计与真空度测量）", "气体成分分析或分压测量（归入分压测量与残余气体分析）", "真空泵的抽气性能或真空系统整体设计（归入真空获得与抽气设备或系统节点）"], "sibling_distinctions": [{"other_code": "N_7e278e61a9e36f1b", "rule": "本节点关注泄漏检测与漏率量化；兄弟节点关注真空度（总压）的常规测量。"}, {"other_code": "N_e8b2ce1947ab532c", "rule": "本节点关注外部气体渗入（泄漏）；兄弟节点关注内部气体成分（残余气体）分析。"}], "cross_boundary_rule": "若研究重点在于检漏仪的传感器原理或信号处理，可次关联至真空计节点；但检漏方法、漏孔标准及泄漏诊断流程主挂载至本节点。"}, {"node_code": "N_e8b2ce1947ab532c", "definition": "研究真空环境下气体成分分析、分压测量原理及残余气体分析（RGA）技术，用于监测真空系统内气体组成与动态变化。", "boundary": "聚焦于真空环境中“气体是什么”及“各组分多少”的分析。包括质谱法、激光光谱法等分压测量技术，残余气体分析（RGA）谱图解析，以及气体放气率与成分监测。边界在于成分与分压信息，不涉及总压测量或泄漏检测。若涉及质谱仪硬件设计，可关联至仪器制造，但真空应用下的气体分析技术归本节点。", "includes": ["质谱法、激光光谱法等真空气体分压测量原理与技术", "残余气体分析（RGA）谱图解析、气体成分识别及动态监测", "真空系统内气体放气率测量、背景气体成分分析及洁净度评估"], "excludes": ["真空度（总压）测量（归入真空计与真空度测量）", "泄漏检测或漏率测量（归入真空检漏、漏孔与校准）", "真空泵的抽气性能或真空系统整体设计（归入真空获得与抽气设备或系统节点）"], "sibling_distinctions": [{"other_code": "N_7e278e61a9e36f1b", "rule": "本节点关注气体成分与分压；兄弟节点关注总压数值。"}, {"other_code": "N_a1c8872f7944e3c6", "rule": "本节点关注内部气体成分（如放气、背景气体）；兄弟节点关注外部气体渗入（泄漏）。"}], "cross_boundary_rule": "若研究重点在于质谱仪等分析仪器本身的硬件设计或通用原理，可次关联至仪器制造或通用分析化学；但在真空技术语境下，针对真空环境的气体成分分析与RGA应用主挂载至本节点。"}]}
